import{_ as s,o as a,c as n,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"OCIRE - OpenCubeOS 独立恢复环境","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/ocire.md","filePath":"zh/dev/ocire.md"}'),t={name:"zh/dev/ocire.md"};function i(c,e,l,p,d,r){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="ocire-opencubeos-独立恢复环境" tabindex="-1">OCIRE - OpenCubeOS 独立恢复环境 <a class="header-anchor" href="#ocire-opencubeos-独立恢复环境" aria-label="Permalink to &quot;OCIRE - OpenCubeOS 独立恢复环境&quot;">​</a></h1><p>由 <strong>3.0.0-WP-02-ocire_recovery</strong> 交付（该工作包交付了恢复特性： 带看门狗式启动失败检测的启动监督器，以及带 syscheck / repair 的完整恢复 shell）。</p><h2 id="ocire-是什么" tabindex="-1">OCIRE 是什么 <a class="header-anchor" href="#ocire-是什么" aria-label="Permalink to &quot;OCIRE 是什么&quot;">​</a></h2><p>OCIRE 是第二个 L0 内核，与 Open Cube OS（OCOS）内核完全独立。 它住在自己的源码树（<code>ocire/</code>）里，不与 OCOS 共享任何头文件， 用自己的链接脚本（<code>ocire/linker_ocire.ld</code>）链接，产出自己的 启动镜像（<code>build/ocire/ocire.iso</code>）。双内核架构：</p><ul><li><strong>L0 = 提供服务</strong> — OCOS 仍是全服务内核。OCIRE 是一个 L0 <em>对等体</em>：在 OCOS 无法启动时启动的恢复内核。</li><li><strong>独立性</strong> — OCIRE 必须能在不触达、不依赖任何 OCOS 代码、 数据或分区的情况下启动、运行并对机器做电源循环。</li></ul><h2 id="wp-01-交付内容" tabindex="-1">WP-01 交付内容 <a class="header-anchor" href="#wp-01-交付内容" aria-label="Permalink to &quot;WP-01 交付内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>WP-01</th><th>WP-02（本包）</th><th>WP-03</th></tr></thead><tbody><tr><td>启动 + 最小 shell</td><td><strong>已完成</strong></td><td>—</td><td>—</td></tr><tr><td>help / shutdown / reboot</td><td><strong>已完成</strong></td><td>—</td><td>—</td></tr><tr><td>恢复特性、FAT12、自检、修复</td><td>—</td><td><strong>此处</strong></td><td>—</td></tr><tr><td>启动失败检测、1 分钟超时</td><td>—</td><td><strong>此处</strong></td><td>—</td></tr><tr><td>OCOS &lt;-&gt; OCIRE 接口、进程保护</td><td>—</td><td>—</td><td>此处</td></tr></tbody></table><h2 id="wp-02-交付内容" tabindex="-1">WP-02 交付内容 <a class="header-anchor" href="#wp-02-交付内容" aria-label="Permalink to &quot;WP-02 交付内容&quot;">​</a></h2><ol><li><strong>启动监督器</strong>（<code>ocire.mode=sup</code>，双启动菜单默认项）：扫描 磁盘、运行邮箱状态机、为 60 秒启动窗口布防 i6300esb 看门狗、 分阶段加载并对 ring-3 日志代理做摘要校验，然后 kexec OCOS 内核并把邮箱 / 日志 / wdt 事实放到命令行上 （<code>oc.log= oc.logsecs= oc.mb= oc.wdt= oc.agent=1</code>）。</li><li><strong>启动失败检测</strong>：一次看门狗复位把监督器落在一个仍是 <code>WAIT_BOOT_SIGNAL</code> 的邮箱上，意味着 OCOS 从未起来 - 监督器 打印崩溃通告、递增 <code>fail_count</code>、设置 <code>ENTER_FULL</code> 并重启 进入完整恢复 shell。已在 QEMU 中用真实 i6300esb 设备 （<code>-device i6300esb</code>）端到端验证：布防 -&gt; kexec -&gt; 60 秒 到期 -&gt; 复位 -&gt; 崩溃通告 -&gt; 恢复 shell。</li><li><strong>完整恢复 shell</strong>（菜单项 2 或 <code>ocire.mode=full</code>）： <code>logread</code>（转储启动日志环）、<code>syscheck</code>（十点完整性自检）、 <code>repair quick</code>（修复 MBR / 邮箱 / 日志头 + 恢复任何摘要与 黄金清单不一致的系统文件）、<code>repair full</code>（对系统卷做破坏性 重格式化 + 完整黄金重写，需输入 YES 确认）、<code>return</code> （正常启动邮箱 + 重启），外加 WP-01 的 <code>help/shutdown/reboot</code>。</li><li><strong>FAT12 读 / FAT32 读写</strong>：流式辅助函数 （<code>ocire_fat_read_range</code>、<code>ocire_fat_hash_file</code>、 <code>ocire_fat_copy_stream</code>）让恢复 shell 无需缓冲即可对数 MB 的文件做哈希与恢复；分配带有预留标记，因此两次连续分配绝不 会交出同一个簇，不符合 8.3 形式的名称会被拒绝而非静默截断。</li></ol><h3 id="诚实的边界-wp-03-范围-属设计如此" tabindex="-1">诚实的边界（WP-03 范围，属设计如此） <a class="header-anchor" href="#诚实的边界-wp-03-范围-属设计如此" aria-label="Permalink to &quot;诚实的边界（WP-03 范围，属设计如此）&quot;">​</a></h3><p>闭环的 OCOS 一侧<strong>不</strong>在本工作包内：OCOS 尚不解析 <code>oc.*</code> 命令行事实，不写 <code>SIGNAL_OK</code> 邮箱状态，不解防/喂狗 i6300esb， 也不拉起注入的代理（代理调用的 <code>L1SVC_CAT_OCIRE</code> 通道尚不 存在）。后果（已测量并声明）：</p><ul><li>在带 i6300esb 的真实硬件上，一次到达 OCOS 的受监督启动在 交接后 60 秒仍会硬复位（没人解防窗口）- 项 3 &quot;Open Cube OS (direct boot)&quot; 是日常使用的过渡路径。</li><li>没有看门狗时（QEMU 默认配置），仅邮箱的信号机制意味着每个 第二次连续的受监督启动都会降级进恢复 shell（无信号 = 推定 崩溃）。恢复 shell 的 <code>return</code> 把邮箱复位为 NONE。</li></ul><h2 id="源码布局-ocire" tabindex="-1">源码布局（ocire/） <a class="header-anchor" href="#源码布局-ocire" aria-label="Permalink to &quot;源码布局（ocire/）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ocire/</span></span>
<span class="line"><span>  ocire_mb2_header.S    multiboot2 header (80x25 text mode request)</span></span>
<span class="line"><span>  ocire_boot.S          32-bit GRUB entry -&gt; GDT + 4 GiB identity map</span></span>
<span class="line"><span>                        -&gt; long mode -&gt; ocire_main; exception stubs</span></span>
<span class="line"><span>  ocire_main.c          kernel entry: console, IDT, ACPI, shell</span></span>
<span class="line"><span>  ocire_console.c/.h    dual console: COM1 115200 + VGA text 0xB8000</span></span>
<span class="line"><span>  ocire_input.c/.h      serial + PS/2 polled input (shift/caps/backsp)</span></span>
<span class="line"><span>  ocire_idt.c/.h        minimal IDT: 32 exception vectors, faults</span></span>
<span class="line"><span>                        print a diagnostic instead of triple-faulting</span></span>
<span class="line"><span>  ocire_acpi.c/.h       RSDP/XSDT/FADT (checksums verified), tiny \\_S5</span></span>
<span class="line"><span>                        package reader, PM1a S5 + RESET_REG + 8042</span></span>
<span class="line"><span>  ocire_mb2.c/.h        multiboot2 info parsing (framebuffer/cmdline/</span></span>
<span class="line"><span>                        modules - WP-02 group 1)</span></span>
<span class="line"><span>  ocire_font.c/.h       embedded 8x16 font for the LFB console</span></span>
<span class="line"><span>  ocire_ata.c/.h        ATA PIO driver (IDENTIFY, LBA28 read/write)</span></span>
<span class="line"><span>  ocire_sha256.c/.h     SHA-256 (golden/agent/kernel digests)</span></span>
<span class="line"><span>  ocire_fat.c/.h        FAT12 read + FAT32 read/write (mount, lookup,</span></span>
<span class="line"><span>                        streaming read/hash/copy, create/mkdir/format)</span></span>
<span class="line"><span>  ocire_wdt.c/.h        Intel 6300ESB watchdog (PCI 8086:25ab probe,</span></span>
<span class="line"><span>                        arm/disarm/ping, 1 kHz two-stage window)</span></span>
<span class="line"><span>  ocire_bootsvc.c/.h    the boot supervisor (mailbox state machine,</span></span>
<span class="line"><span>                        agent staging, kexec hand-over)</span></span>
<span class="line"><span>  ocire_kexec.c/.h      OCOS ELF staging + mb2 info rebuild + jump</span></span>
<span class="line"><span>  ocire_kexec_jump.S    64-bit kexec trampoline</span></span>
<span class="line"><span>  ocire_disk.c/.h       recovery-disk discovery, mailbox, golden image</span></span>
<span class="line"><span>  ocire_recover.c/.h    the full recovery shell commands (logread/</span></span>
<span class="line"><span>                        syscheck/repair/return)</span></span>
<span class="line"><span>  ocire_shell.c/.h      the command loop (8 commands)</span></span>
<span class="line"><span>  ocire_util.c/.h       freestanding mem/string helpers</span></span>
<span class="line"><span>  ocire_io.h            port I/O inline helpers</span></span>
<span class="line"><span>  ocire_types.h         base scalar types</span></span>
<span class="line"><span>  agent/ocire_agent.c   the ring-3 log agent (OCOS L1 ABI, injected</span></span>
<span class="line"><span>                        at kexec; its L1SVC channel is WP-03)</span></span>
<span class="line"><span>  ocire.mk              build targets (included from the top Makefile)</span></span>
<span class="line"><span>  linker_ocire.ld       own link layout (1 MiB load address)</span></span>
<span class="line"><span>  grub-ocire.cfg        standalone ISO menu (single entry)</span></span>
<span class="line"><span>  grub-dual.cfg.in      dual-boot disk menu TEMPLATE (3 entries:</span></span>
<span class="line"><span>                        supervisor default, full shell, direct OCOS)</span></span></code></pre></div><p>构建目标：<code>make ocire-kernel</code>、<code>make ocire-iso</code>、<code>make ocire-disk</code>、<code>make ocire-test</code>、<code>make ocire-dual-test</code>、<code>make ocire-shell-test</code>（运行目标 <code>ocire-run-bios/uefi[-gui]</code> 同样 可用）。编译使用与 OCOS 内核相同的 <code>-Wall -Wextra -Werror</code> 零警告门禁；CI 在每次 push 时运行 OCIRE 构建。OCIRE 的目标 文件在 ocire.mk 中携带自己的 <code>-include $(OCIRE_OBJ_C:.o=.d)</code> 头依赖跟踪（顶层 Makefile 只包含 OCOS 内核的 .d 文件 - ocire/ 中的头文件改动曾静默链接过期对象；由 WP-02 批次现场发现并 修复）。</p><h2 id="两个操作系统如何共存-wp-01-布局" tabindex="-1">两个操作系统如何共存（WP-01 布局） <a class="header-anchor" href="#两个操作系统如何共存-wp-01-布局" aria-label="Permalink to &quot;两个操作系统如何共存（WP-01 布局）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hd0 (ocire-boot.img, built by tools/make_ocire_disk.sh)</span></span>
<span class="line"><span>  MBR + GRUB (BIOS: boot.img + core.img in the post-MBR gap;</span></span>
<span class="line"><span>              UEFI: /EFI/BOOT/BOOTX64.EFI on the FAT32 partition)</span></span>
<span class="line"><span>  p1 FAT32: /boot/opencube.elf (OCOS kernel)</span></span>
<span class="line"><span>            /boot/ocire.elf    (copy of the OCIRE kernel)</span></span>
<span class="line"><span>            /boot/grub/grub.cfg (the dual menu)</span></span>
<span class="line"><span>  -&gt; GRUB menu entry 1 boots OCOS (default)</span></span>
<span class="line"><span>  -&gt; GRUB menu entry 2 boots OCIRE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hd1 (ocire-hd.img) - the OCIRE disk</span></span>
<span class="line"><span>  MBR with ONE entry, type 0xEE (&quot;GPT protective shadow&quot;), no GPT</span></span>
<span class="line"><span>  header behind it; the raw OCIRE kernel image is stored at the</span></span>
<span class="line"><span>  partition start (LBA 2048).</span></span>
<span class="line"><span>  -&gt; the GRUB menu loads it with a whole-disk blocklist:</span></span>
<span class="line"><span>     multiboot2 (hd1)2048+128</span></span>
<span class="line"><span>  -&gt; OCOS refuses the entire partition table (0xEE makes its parser</span></span>
<span class="line"><span>     switch to GPT mode, which fails without a GPT header), so the</span></span>
<span class="line"><span>     OCIRE partition has no device node and no filesystem path in</span></span>
<span class="line"><span>     OCOS - see &quot;Partition isolation&quot; below.</span></span></code></pre></div><p>点亮过程留下的两条教训，记录在此：</p><ol><li>GRUB 2.12 的 msdos 分区表<strong>跳过</strong> 0xEE 项 — 即便同一个项 在磁盘上完全合法，<code>(hd1,msdos1)</code> 这样的分区路径对 GRUB 也 不存在。因此菜单使用整盘块清单。</li><li>GRUB 菜单没有数字热键；自动化通过串口菜单终端上的 ANSI 光标下移序列选择项。</li></ol><h2 id="分区隔离-wp-01-验收测试" tabindex="-1">分区隔离（WP-01 验收测试） <a class="header-anchor" href="#分区隔离-wp-01-验收测试" aria-label="Permalink to &quot;分区隔离（WP-01 验收测试）&quot;">​</a></h2><p>在挂着两块磁盘的运行中 OCOS 里测得，见 <code>evidence/3_0_0_wp01_ocire/isolation.log</code>：</p><ul><li><code>partscan: 1 partition device(s) registered</code> — OCIRE 磁盘 贡献<strong>零</strong>个子设备（只有双启动盘的 p1 注册）。</li><li><code>parted hda</code>（OCIRE 磁盘）→ <code>no partition table found</code>。</li><li><code>mkfs.fat32 hdap1 confirm</code> → <code>device not found</code> — 没有可写 入的节点。</li><li><code>disk_rw_test hdap1</code> → <code>device lookup FAIL</code> — 没有可读取的 节点。</li><li><code>df</code> — 只挂载了 OCOS 卷；来自 OCIRE 磁盘的一无所有。</li></ul><p>诚实的边界（同样已测，<code>isolation_rawdecl.log</code>）：整盘设备节点 仍然存在 — <code>disk_rw_test hda</code> 与 <code>mkfs.fat32 hda confirm</code> 在 一次性副本上都能工作，恰如带 <code>/dev/sdb</code> 的 Linux root。要阻止 管理员级的整盘操作需要 OCOS 块层策略 — 这是本工作包明确禁止 的 OCOS 内核改动 — 属于 WP-03（进程保护）。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><ul><li><code>tools/run_ocire_tests.py</code>（<code>make ocire-test</code>）— 14 个用例， BIOS + UEFI：启动到 shell 提示符、<code>help</code>、未知命令提示、 退格编辑、<code>shutdown</code>（ACPI S5；QEMU 真的退出）和 <code>reboot</code> （8042/RESET_REG；带 <code>-no-reboot</code> 时 QEMU 真的退出）。</li><li><code>tools/run_ocire_dual_tests.py</code>（<code>make ocire-dual-test</code>）— 11 个用例：在一次性磁盘副本上跑四种双启动组合（BIOS/UEFI x 菜单默认监督器-&gt;kexec-&gt;OCOS / 菜单选择 OCIRE 完整 shell） （监督器有状态 - 见 WP-03 边界）、五项隔离探针和两项整盘声明 探针。</li><li><code>tools/run_ocire_shell_tests.py</code>（<code>make ocire-shell-test</code>）— WP-02 恢复批次，在一次性副本上的 4 个用例：<code>shell_healthy</code> （在 pristine 磁盘上 syscheck 10/10 + 幂等的 quick 修复）、 <code>shell_quick_repair</code>（内核 ELF 翻转一个字节 -&gt; syscheck 抓住 摘要不匹配 -&gt; repair quick 恢复并验证 -&gt; 重新健康）、 <code>shell_full_repair</code>（p1 BPB 被清零 -&gt; 从独立 ISO 启动，hd0 自己的 GRUB 已读不出它的配置 -&gt; repair full 从黄金镜像重写 该卷 -&gt; 恢复健康）以及 <code>shell_wdt_timeout</code>（挂上真实 i6300esb：监督器布防 60 秒窗口 -&gt; kexec -&gt; OCOS 启动但从不 发信号 -&gt; 看门狗复位 -&gt; 崩溃通告 -&gt; 完整恢复 shell）。</li><li>在一棵含 OCIRE 但零 OCOS 改动的树上跑完整 OCOS 回归矩阵： <code>evidence/3_0_0_wp01_ocire/regression/</code>（宿主机测试、 reproducible-check、wp12、wp10_tui、chinese、tuiqa x2、 native x2、l1_per_app、wait4 全新启动批次 20/20、启动门禁） — 全绿且与 2.2.0 发布基线一致。</li></ul>`,25)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
